  data: blob.stream(),
  type: blob.type,
  colorSpaceConversion: "none",
  preferAnimation: false
})

try {
  // Returns a VideoFrame; caller is responsible for calling .close() on it.
  const { image } = await decoder.decode()
  return image
} finally {
  decoder.close()
